import React, { useState, useEffect, useRef } from 'react';
import './SearchWidget.css';

// Global state for search monitoring
let searchMonitor = null;

const SearchWidget = ({ onClose, isVisible = true, initialQuery }) => {
  const [result, setResult] = useState('Ready to search...');
  const [activeTab, setActiveTab] = useState('current'); // 'current' or 'history'
  const [isLoading, setIsLoading] = useState(false);
  const [searchHistory, setSearchHistory] = useState([]);
  const [autoShow, setAutoShow] = useState(false); // New state to track auto-showing

  // Custom Drag & Resize State
  const [widgetPos, setWidgetPos] = useState({ x: 100, y: 100 });
  const [widgetSize, setWidgetSize] = useState({ width: 550, height: 400 });
  const [isDragging, setIsDragging] = useState(false);
  const [isResizing, setIsResizing] = useState(false);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });

  const widgetRef = useRef(null);
  const resizeStartRef = useRef({ x: 0, y: 0, width: 0, height: 0 });

  // Initialize position and load history
  useEffect(() => {
    console.log("[DEBUG] SearchWidget mounted");
    // 12vh from top, centered horizontally
    const startX = (window.innerWidth / 2) - 275;
    const startY = window.innerHeight * 0.12;
    setWidgetPos({ x: startX, y: startY });

    const savedHistory = localStorage.getItem('astra_search_history');
    if (savedHistory) {
      try {
        setSearchHistory(JSON.parse(savedHistory));
      } catch (e) {
        console.error('Error loading search history:', e);
      }
    }

    // Initialize search monitor
    initializeSearchMonitor();

    return () => {
      console.log("[DEBUG] SearchWidget unmounted");
      // Cleanup search monitor
      if (searchMonitor) {
        searchMonitor.cleanup();
        searchMonitor = null;
      }
    };
  }, []);

  // Initialize search monitoring system
  const initializeSearchMonitor = () => {
    if (!searchMonitor) {
      searchMonitor = new SearchMonitor(setAutoShow, setResult, setSearchHistory);
      searchMonitor.startMonitoring();
    }
  };

  // Search Monitor Class
  class SearchMonitor {
    constructor(setAutoShowCallback, setResultCallback, setSearchHistoryCallback) {
      this.setAutoshow = setAutoShowCallback;
      this.setResult = setResultCallback;
      this.setSearchHistory = setSearchHistoryCallback;
      this.monitoringInterval = null;
      this.lastChecked = Date.now();
      this.lastSearchIds = new Set();
      this.currentSearchResults = {};
    }

    startMonitoring() {
      console.log("[SEARCH MONITOR] Starting search monitoring...");
      // Check for search results periodically
      this.monitoringInterval = setInterval(() => {
        this.checkForNewSearchResults();
      }, 1000); // Check every second
    }

    async checkForNewSearchResults() {
      try {
        // Check for new search results from the AI system
        const response = await fetch('/api/search_results.json'); // Assuming this is where search results are stored

        if (response.ok) {
          const data = await response.json();

          // Process search results
          if (data && Array.isArray(data.search_results)) {
            for (const searchResult of data.search_results) {
              const searchId = searchResult.search_id || searchResult.id;

              if (searchId && !this.lastSearchIds.has(searchId)) {
                console.log("[SEARCH MONITOR] New search result detected:", searchId);

                // Add to known search IDs to avoid duplicates
                this.lastSearchIds.add(searchId);

                // Store the search result
                this.currentSearchResults[searchId] = searchResult;

                // Automatically show the search widget with the new results
                this.displaySearchResult(searchResult);
              }
            }
          }
        } else {
          // Alternative: Check for search results in a different format
          // This could be from @--- file or other source
          await this.checkAlternativeSources();
        }
      } catch (error) {
        console.log("[SEARCH MONITOR] Error checking for search results:", error.message);
        // Continue monitoring despite errors
      }
    }

    async checkAlternativeSources() {
      // Check for search results in alternative locations
      // This could be the @--- file mentioned in the requirements
      try {
        // Try to fetch from a common search results endpoint
        const response = await fetch('/api/unified_messages.json');

        if (response.ok) {
          const data = await response.json();

          if (data && Array.isArray(data)) {
            for (const message of data) {
              if (message.search_id && !this.lastSearchIds.has(message.search_id)) {
                console.log("[SEARCH MONITOR] New search result from unified messages:", message.search_id);

                this.lastSearchIds.add(message.search_id);
                this.displaySearchResult(message);
              }
            }
          }
        }
      } catch (error) {
        console.log("[SEARCH MONITOR] Error checking alternative sources:", error.message);
      }
    }

    displaySearchResult(searchResult) {
      console.log("[SEARCH MONITOR] Displaying search result:", searchResult);

      // Set the result in the widget
      const content = searchResult.content || searchResult.result || searchResult.response || JSON.stringify(searchResult);
      this.setResult(content);

      // Add to search history
      const historyItem = {
        id: searchResult.search_id || Date.now(),
        query: searchResult.query || searchResult.question || 'Search Query',
        result: content,
        timestamp: new Date().toISOString(),
        date: new Date().toLocaleString()
      };

      // Get current history and add new item
      const currentHistory = this.setSearchHistory ? [] : [];
      const updatedHistory = [historyItem, ...currentHistory].slice(0, 50);
      this.setSearchHistory(updatedHistory);
      localStorage.setItem('astra_search_history', JSON.stringify(updatedHistory));

      // Trigger auto-show of the widget
      this.setAutoshow(true);

      // Set active tab to current
      setActiveTab('current');

      // Animation trigger
      if (widgetRef.current) {
        widgetRef.current.style.animation = 'none';
        setTimeout(() => {
          if (widgetRef.current) widgetRef.current.style.animation = 'searchGlow 3s ease-in-out infinite';
        }, 10);
      }
    }

    cleanup() {
      if (this.monitoringInterval) {
        clearInterval(this.monitoringInterval);
        this.monitoringInterval = null;
      }
      console.log("[SEARCH MONITOR] Monitoring stopped");
    }
  }

  // Handle incoming search results from AI
  useEffect(() => {
    if (initialQuery) {
      console.log("[DEBUG] SearchWidget received initialQuery:", initialQuery);
      const content = typeof initialQuery === 'object' ? initialQuery.content : initialQuery;
      handleNewSearch(content);
    }
  }, [initialQuery]);

  const handleNewSearch = async (content) => {
    if (!content) return;
    setIsLoading(true);
    setActiveTab('current');

    // Clean up content if it contains the SEARCH_RESULT prefix
    let cleanContent = content;
    if (typeof content === 'string') {
      cleanContent = content.replace(/^SEARCH_RESULT:\s*/, '').replace(/^SEARCH RESULT\s*/, '').trim();
    }

    setResult(cleanContent);
    setIsLoading(false);

    // Add to history
    const historyItem = {
      id: Date.now(),
      query: content.substring(0, 30) + (content.length > 30 ? '...' : ''),
      result: content,
      timestamp: new Date().toISOString(),
      date: new Date().toLocaleString()
    };

    const updatedHistory = [historyItem, ...searchHistory].slice(0, 50);
    setSearchHistory(updatedHistory);
    localStorage.setItem('astra_search_history', JSON.stringify(updatedHistory));

    // Animation trigger
    if (widgetRef.current) {
      widgetRef.current.style.animation = 'none';
      setTimeout(() => {
        if (widgetRef.current) widgetRef.current.style.animation = 'searchGlow 3s ease-in-out infinite';
      }, 10);
    }
  };

  // Drag handles
  useEffect(() => {
    if (!isDragging) return;
    const onMove = (e) => {
      setWidgetPos({
        x: e.clientX - dragOffset.x,
        y: e.clientY - dragOffset.y
      });
    };
    const onUp = () => setIsDragging(false);
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    return () => {
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
    };
  }, [isDragging, dragOffset]);

  // Resize handles
  useEffect(() => {
    if (!isResizing) return;
    const onMove = (e) => {
      const deltaX = e.clientX - resizeStartRef.current.x;
      const deltaY = e.clientY - resizeStartRef.current.y;
      setWidgetSize({
        width: Math.max(300, resizeStartRef.current.width + deltaX),
        height: Math.max(200, resizeStartRef.current.height + deltaY)
      });
    };
    const onUp = () => setIsResizing(false);
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    return () => {
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
    };
  }, [isResizing]);

  const handleDragStart = (e) => {
    if (e.target.closest('.widget-controls') || e.target.closest('.resize-handle') || e.target.closest('.search-nav') || e.target.closest('.copy-button')) return;
    setIsDragging(true);
    setDragOffset({
      x: e.clientX - widgetPos.x,
      y: e.clientY - widgetPos.y
    });
  };

  const handleResizeStart = (e) => {
    e.preventDefault();
    setIsResizing(true);
    resizeStartRef.current = {
      x: e.clientX,
      y: e.clientY,
      width: widgetSize.width,
      height: widgetSize.height
    };
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(result);
  };

  const viewHistoryItem = (item) => {
    setResult(item.result);
    setActiveTab('current');
  };

  // if (!isVisible) return null; // Removed as visibility is handled in App.jsx rendering logic

  return (
    <div
      className={`search-widget ${isDragging ? 'widget-dragging' : ''}`}
      ref={widgetRef}
      style={{
        left: `${widgetPos.x}px`,
        top: `${widgetPos.y}px`,
        width: `${widgetSize.width}px`,
        height: `${widgetSize.height}px`,
        position: 'fixed',
        zIndex: 1000
      }}
      onMouseDown={handleDragStart}
    >
      {/* Corner Brackets */}
      <div className="corner-top-right"></div>
      <div className="corner-bottom-left"></div>

      {/* Widget Controls */}
      <div className="widget-controls">
        <div className="widget-control-btn" onClick={() => setWidgetSize(s => ({ width: s.width + 50, height: s.height + 50 }))} title="Make Bigger">⧨</div>
        <div className="widget-control-btn" onClick={() => setWidgetSize(s => ({ width: Math.max(300, s.width - 50), height: Math.max(200, s.height - 50) }))} title="Make Smaller">⧩</div>
        <div className="widget-control-btn" onClick={onClose} title="Close">⧬</div>
      </div>

      <div className="resize-handle" onMouseDown={handleResizeStart}></div>

      {/* Header Label */}
      <div className="search-label">SEARCH</div>

      {/* Navigation Tabs */}
      <div className="search-nav">
        <div
          className={`search-nav-tab ${activeTab === 'current' ? 'active' : ''}`}
          onClick={() => setActiveTab('current')}
        >
          Current
        </div>
        <div
          className={`search-nav-tab ${activeTab === 'history' ? 'active' : ''}`}
          onClick={() => setActiveTab('history')}
        >
          History
        </div>
      </div>

      {/* Content Area */}
      <div className="search-content-wrapper">
        {activeTab === 'current' ? (
          <>
            <div className={`search-content ${isLoading ? 'hidden' : ''}`}>
              {result}
            </div>
            {isLoading && (
              <div className="search-loading">Searching...</div>
            )}
            {!isLoading && (
              <button className="copy-button" onClick={copyToClipboard} title="Copy results">
                <svg viewBox="0 0 24 24" width="16" height="16">
                  <path fill="currentColor" d="M16 1H4C2.9 1 2 1.9 2 3V15H4V3H16V1ZM19 5H8C6.9 5 6 5.9 6 7V21C6 22.1 6.9 23 8 23H19C20.1 23 21 22.1 21 21V7C21 5.9 20.1 5 19 5ZM19 21H8V7H19V21Z" />
                </svg>
              </button>
            )}
          </>
        ) : (
          <div className="search-history">
            {searchHistory.length === 0 ? (
              <div className="search-history-empty">No search history yet</div>
            ) : (
              searchHistory.map(item => (
                <div key={item.id} className="search-history-item" onClick={() => viewHistoryItem(item)}>
                  <div className="search-history-query">{item.query}</div>
                  <div className="search-history-date">{item.date}</div>
                  <div className="search-history-preview">{item.result.substring(0, 80)}...</div>
                </div>
              ))
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default SearchWidget;
